#users-container tbody tr.r-red{background:#fff5f4}
/* ترتيب وضبط الجدول: الإجراءات أول عمود من اليمين وثابتة، وخلايا أصغر */
#users-container th,#users-container td{padding:9px 8px;font-size:13px;vertical-align:middle}
#users-container td.act{white-space:nowrap}
#users-container td.act .action-buttons{flex-direction:column;gap:6px;align-items:stretch}
#users-container td.act .btn{padding:6px 10px;font-size:12px;width:100%}
#users-container td.em{max-width:190px;word-break:break-all}
#users-container td.upd{font-size:11px;color:#777;max-width:150px;word-break:break-all}

